// AUTO-GENERATED from "Business Purchase Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will provide Business Purchase Management Services to assist the Client in identifying, evaluating, negotiating and coordinating the purchase of a suitable business.</p><p style=\"margin:6px 0;\">The specific services, pricing and project requirements for each engagement will be confirmed in the approved Quotation and Work Order.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">all outstanding payments have been made; and</li><li style=\"margin:2px 0;\">all obligations under this Agreement have been fulfilled,</li></ul><p style=\"margin:6px 0;\">unless terminated earlier in accordance with this Agreement.</p><p style=\"margin:6px 0;\">Where ongoing acquisition support services are engaged, this Agreement continues for the period specified in the approved Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">The Client may request one or more of the following services.</p><p style=\"margin:6px 0;\">Only the services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Purchase Consultation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Buyer Requirement Assessment</li><li style=\"margin:2px 0;\">☐ Acquisition Strategy</li><li style=\"margin:2px 0;\">☐ Investment Planning</li><li style=\"margin:2px 0;\">☐ Market Opportunity Assessment</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Search &amp; Shortlisting</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Search</li><li style=\"margin:2px 0;\">☐ Business Shortlisting</li><li style=\"margin:2px 0;\">☐ Opportunity Assessment</li><li style=\"margin:2px 0;\">☐ Seller Matching</li><li style=\"margin:2px 0;\">☐ Market Comparison</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Inspection</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Business Presentation Coordination</li><li style=\"margin:2px 0;\">☐ Operational Walkthrough Coordination</li><li style=\"margin:2px 0;\">☐ Seller Meeting Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Negotiation &amp; Transaction Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Offer Coordination</li><li style=\"margin:2px 0;\">☐ Purchase Negotiation Coordination</li><li style=\"margin:2px 0;\">☐ Seller Communication</li><li style=\"margin:2px 0;\">☐ Transaction Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Due Diligence &amp; Documentation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Due Diligence Coordination</li><li style=\"margin:2px 0;\">☐ Financial Information Coordination</li><li style=\"margin:2px 0;\">☐ Legal Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Purchase Agreement Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Post-Purchase Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Handover Coordination</li><li style=\"margin:2px 0;\">☐ Utility Transfer Coordination</li><li style=\"margin:2px 0;\">☐ Licence Transfer Coordination</li><li style=\"margin:2px 0;\">☐ Post-Settlement Support</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Legal Adviser Coordination</li><li style=\"margin:2px 0;\">☐ Accounting Adviser Coordination</li><li style=\"margin:2px 0;\">☐ Finance Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional services may be included by written agreement.</p>"],
  ["BUYER REQUIREMENTS", "<p style=\"margin:6px 0;\">The details of each engagement shall be recorded in Schedule B or the approved Work Order, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Client Name;</li><li style=\"margin:2px 0;\">Intended Business Type;</li><li style=\"margin:2px 0;\">Preferred Location;</li><li style=\"margin:2px 0;\">Investment Budget;</li><li style=\"margin:2px 0;\">Purchase Purpose;</li><li style=\"margin:2px 0;\">Preferred Industry;</li><li style=\"margin:2px 0;\">Selected Services;</li><li style=\"margin:2px 0;\">Agreed Pricing;</li><li style=\"margin:2px 0;\">Project Timeline; and</li><li style=\"margin:2px 0;\">Special Requirements.</li></ul><p style=\"margin:6px 0;\">If any inconsistency exists between this Agreement and the Work Order, the Work Order prevails for that project only.</p>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">understand the Client's acquisition requirements;</li><li style=\"margin:2px 0;\">identify and shortlist suitable business opportunities;</li><li style=\"margin:2px 0;\">coordinate inspections and seller meetings;</li><li style=\"margin:2px 0;\">facilitate communication with sellers where authorised;</li><li style=\"margin:2px 0;\">coordinate negotiations and due diligence activities;</li><li style=\"margin:2px 0;\">coordinate documentation and settlement activities where requested;</li><li style=\"margin:2px 0;\">provide regular progress updates; and</li><li style=\"margin:2px 0;\">use reasonable care and skill in delivering the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as the Client's business acquisition consultant and transaction coordinator and is not the seller, broker, legal adviser, accountant or financial adviser for the transaction.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate information regarding investment objectives and financial capacity;</li><li style=\"margin:2px 0;\">promptly provide documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">advise Seventh Sky of any changes to acquisition requirements;</li><li style=\"margin:2px 0;\">attend inspections and meetings where reasonably required;</li><li style=\"margin:2px 0;\">obtain independent legal, accounting, taxation and financial advice before completing any purchase;</li><li style=\"margin:2px 0;\">pay all agreed fees in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">cooperate throughout the acquisition process.</li></ul><p style=\"margin:6px 0;\">The Client remains responsible for all investment decisions and for conducting appropriate commercial, legal and financial due diligence before purchasing a business.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before work commences, Seventh Sky will provide a Quotation and, where applicable, a Work Order setting out:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">selected services;</li><li style=\"margin:2px 0;\">scope of work;</li><li style=\"margin:2px 0;\">estimated project timeline;</li><li style=\"margin:2px 0;\">agreed fees;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected deliverables; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Services will commence once the Client accepts the Quotation or Work Order.</p><p style=\"margin:6px 0;\">Where the Client requests additional services after acceptance, a revised quotation or approved variation may be issued.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The total project cost will be specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">buyer requirement assessment;</li><li style=\"margin:2px 0;\">business search and shortlisting;</li><li style=\"margin:2px 0;\">market opportunity assessment;</li><li style=\"margin:2px 0;\">business inspection coordination;</li><li style=\"margin:2px 0;\">negotiation coordination;</li><li style=\"margin:2px 0;\">due diligence coordination;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">acquisition management services;</li><li style=\"margin:2px 0;\">approved third-party service fees (where applicable); and</li><li style=\"margin:2px 0;\">any approved additional services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay all agreed fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Legal fees, accounting fees, valuation fees, government charges, taxes, stamp duty, financing costs and other third-party expenses are payable by the Client unless otherwise stated in the approved Quotation or Work Order.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:6px 0;\">Business Purchase Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order.</li></ul><p style=\"margin:6px 0;\">Progress payment (where applicable).</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or settlement of the business purchase, whichever occurs first.</li></ul><p style=\"margin:6px 0;\">Ongoing Acquisition Support Services</p><p style=\"margin:6px 0;\">Where the Client engages Seventh Sky for ongoing acquisition support, payment may be made:</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Weekly</li><li style=\"margin:2px 0;\">☐ Monthly</li><li style=\"margin:2px 0;\">☐ Quarterly</li><li style=\"margin:2px 0;\">☐ Annually</li></ul><p style=\"margin:6px 0;\">as specified in the approved Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services.</p>"],
  ["BUSINESS SEARCH, BUYER SUPPORT & ACQUISITION COORDINATION", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to identify suitable business opportunities based on the Client's stated requirements.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">suitable business opportunities are subject to market availability;</li><li style=\"margin:2px 0;\">sellers have the right to decide whether to proceed with a sale;</li><li style=\"margin:2px 0;\">asking prices and business values may change during negotiations;</li><li style=\"margin:2px 0;\">successful acquisition of a business cannot be guaranteed; and</li><li style=\"margin:2px 0;\">the final purchase agreement remains subject to mutual acceptance between the Client and the seller.</li></ul><p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">business searches;</li><li style=\"margin:2px 0;\">inspections;</li><li style=\"margin:2px 0;\">seller meetings;</li><li style=\"margin:2px 0;\">preliminary negotiations;</li><li style=\"margin:2px 0;\">due diligence coordination;</li><li style=\"margin:2px 0;\">documentation;</li><li style=\"margin:2px 0;\">settlement activities; and</li><li style=\"margin:2px 0;\">post-purchase coordination.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">availability of suitable businesses;</li><li style=\"margin:2px 0;\">seller response times;</li><li style=\"margin:2px 0;\">negotiations between the parties;</li><li style=\"margin:2px 0;\">due diligence processes;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">regulatory requirements;</li><li style=\"margin:2px 0;\">public holidays; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional business searches;</li><li style=\"margin:2px 0;\">expanded market research;</li><li style=\"margin:2px 0;\">additional inspections;</li><li style=\"margin:2px 0;\">extended negotiations;</li><li style=\"margin:2px 0;\">additional due diligence coordination;</li><li style=\"margin:2px 0;\">finance coordination;</li><li style=\"margin:2px 0;\">legal or accounting adviser coordination;</li><li style=\"margin:2px 0;\">settlement extensions; or</li><li style=\"margin:2px 0;\">any other Client-requested services.</li></ul><p style=\"margin:6px 0;\">Where practical, Seventh Sky will advise the Client of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the additional work;</li><li style=\"margin:2px 0;\">any additional charges; and</li><li style=\"margin:2px 0;\">any expected impact on the project timeline.</li></ul><p style=\"margin:6px 0;\">No variation will proceed without the Client's approval unless immediate action is reasonably necessary to protect the Client's interests.</p>"],
  ["DUE DILIGENCE & THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate due diligence activities and facilitate communication with third-party professionals.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">due diligence findings depend on the information made available by the seller and relevant third parties;</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee the accuracy or completeness of information provided by sellers or third parties;</li><li style=\"margin:2px 0;\">the Client remains responsible for making the final decision to purchase the business; and</li><li style=\"margin:2px 0;\">lawyers, accountants, valuers, finance providers, taxation advisers and other independent professionals remain responsible for their own advice and services.</li></ul><p style=\"margin:6px 0;\">Seventh Sky remains responsible for coordinating the Services requested by the Client with reasonable care and skill.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be considered completed when the agreed scope of work specified in the Quotation or Work Order has been substantially delivered.</p><p style=\"margin:6px 0;\">Depending on the selected services, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">suitable businesses identified and shortlisted;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations coordinated;</li><li style=\"margin:2px 0;\">due diligence coordination completed;</li><li style=\"margin:2px 0;\">purchase documentation coordinated;</li><li style=\"margin:2px 0;\">settlement completed;</li><li style=\"margin:2px 0;\">business handover coordinated; or</li><li style=\"margin:2px 0;\">ongoing acquisition support services delivered for the agreed service period.</li></ul><p style=\"margin:6px 0;\">Where ongoing acquisition support services are engaged, completion shall occur at the expiry of the agreed service period unless renewed by mutual agreement.</p>"],
  ["CLIENT COMPLAINTS & SERVICE ISSUES", "<p style=\"margin:6px 0;\">If the Client believes that the Services have not been delivered in accordance with the agreed scope, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">liaise with relevant parties where appropriate;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue; and</li><li style=\"margin:2px 0;\">keep the Client informed of the outcome.</li></ul><p style=\"margin:6px 0;\">Where the issue arises from Seventh Sky's administrative oversight, reasonable efforts will be made to rectify the matter promptly.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available to the Client under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">To the extent permitted by the laws of Bangladesh:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Seventh Sky will provide the Services with reasonable care and skill.</li><li style=\"margin:2px 0;\">Seventh Sky is responsible only for the Services it has agreed to provide under this Agreement.</li><li style=\"margin:2px 0;\">Sellers remain responsible for the information they provide regarding the business.</li></ul><p style=\"margin:6px 0;\">The Client remains responsible for all commercial, financial and investment decisions relating to the purchase.</p><p style=\"margin:6px 0;\">Independent professionals, including lawyers, accountants, valuers, finance providers and tax advisers, remain responsible for their own advice and services.</p><p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failures resulting from circumstances beyond their reasonable control.</p>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">Except where liability cannot legally be excluded or limited, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">a seller deciding not to proceed with the sale;</li><li style=\"margin:2px 0;\">the Client deciding not to proceed with the purchase;</li><li style=\"margin:2px 0;\">delays caused by negotiations, finance approval, due diligence or regulatory requirements;</li><li style=\"margin:2px 0;\">changes in business value, asking price or market conditions;</li><li style=\"margin:2px 0;\">inaccurate or incomplete information provided by sellers, the Client or third parties;</li><li style=\"margin:2px 0;\">the actions or omissions of independent professionals;</li><li style=\"margin:2px 0;\">business interruption;</li><li style=\"margin:2px 0;\">loss of business opportunity, profit or goodwill; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where permitted by law, Seventh Sky's total liability arising from a project shall not exceed the amount paid by the Client for the affected Services.</p><p style=\"margin:6px 0;\">This clause does not exclude liability arising from fraud, wilful misconduct or any liability that cannot legally be excluded.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Each Party agrees to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Business and personal information will only be collected, used and disclosed for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the requested Services;</li><li style=\"margin:2px 0;\">identifying and assessing suitable business opportunities;</li><li style=\"margin:2px 0;\">communicating with the Client, sellers and authorised representatives;</li><li style=\"margin:2px 0;\">coordinating with lawyers, accountants, valuers, finance providers and other authorised third parties;</li><li style=\"margin:2px 0;\">preparing quotations, Work Orders and invoices;</li><li style=\"margin:2px 0;\">complying with legal obligations; or</li><li style=\"margin:2px 0;\">other purposes authorised by the Client.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform caused by circumstances beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">severe weather;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">civil unrest;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">major technology failures;</li><li style=\"margin:2px 0;\">financial system disruptions; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have reviewed and accepted the Quotation or Work Order before the Services commence;</li><li style=\"margin:2px 0;\">suitable business opportunities are subject to market availability;</li><li style=\"margin:2px 0;\">the final decision to purchase a business remains solely with the Client;</li><li style=\"margin:2px 0;\">sellers may withdraw or amend their offers during negotiations or due diligence;</li><li style=\"margin:2px 0;\">independent legal, accounting, taxation and financial advice should be obtained before completing any business purchase;</li><li style=\"margin:2px 0;\">some Services involve coordination with independent third parties; and</li><li style=\"margin:2px 0;\">they have had the opportunity to ask questions and obtain independent professional advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend the Services where:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the Client fails to make payment in accordance with this Agreement;</li><li style=\"margin:2px 0;\">the Client fails to provide information or documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">the Client provides false, misleading or fraudulent information;</li><li style=\"margin:2px 0;\">the Client requests suspension; or</li><li style=\"margin:2px 0;\">continuation of the Services would be unlawful or impracticable.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing thirty (30) days' written notice, provided all completed Services and outstanding payments have been settled.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">provides false or fraudulent information;</li><li style=\"margin:2px 0;\">fails to make payment after receiving written notice;</li><li style=\"margin:2px 0;\">engages in unlawful conduct; or</li><li style=\"margin:2px 0;\">prevents Seventh Sky from performing the agreed Services.</li></ul><p style=\"margin:6px 0;\">Where the Client terminates after Services have commenced, the Client remains responsible for payment for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Services already completed;</li><li style=\"margin:2px 0;\">business search and buyer support activities undertaken;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations coordinated;</li><li style=\"margin:2px 0;\">approved third-party costs incurred; and</li><li style=\"margin:2px 0;\">other reasonable expenses incurred before termination.</li></ul><p style=\"margin:6px 0;\">Termination does not affect any rights or obligations that arose before the termination date.</p>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky invests significant time, expertise and commercial resources in identifying suitable business opportunities and coordinating introductions.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a business opportunity, seller or authorised representative to the Client, the Client agrees that, during the term of this Agreement and for twelve (12) months after the introduction, the Client will not intentionally bypass Seventh Sky to negotiate or complete the purchase of the introduced business without Seventh Sky's prior written consent.</p><p style=\"margin:6px 0;\">Where the Client purchases a business introduced by Seventh Sky during this period, the agreed service fees or success fees specified in the approved Quotation or Work Order remain payable.</p><p style=\"margin:6px 0;\">This clause does not restrict the Client from purchasing a business that was not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment must be made in writing and signed or electronically accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision does not waive its rights;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall continue in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, courier, registered post or email.</li></ul>"],
  ["GOVERNING LAW & DISPUTE RESOLUTION", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to make reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">If the dispute cannot be resolved through negotiation, the Parties may agree to mediation or another recognised alternative dispute resolution process before referring the matter to the competent courts of Bangladesh.</p><p style=\"margin:6px 0;\">Nothing in this clause prevents either Party from seeking urgent legal or equitable relief where necessary.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal, financial, taxation and professional advice;</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily; and</li><li style=\"margin:2px 0;\">agree to be legally bound by its terms.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, including through approved electronic signature platforms such as DocuSign. Each signed copy shall be deemed an original and together constitute one Agreement.</p>"],
];
